use crate::packet::{Context,Cover};use crate::verifier;pub fn qualify(context:&Context,cover:&Cover){let c=&context.c;let (d,target,ell,sm,p,cc,k)=(context.d,context.target,context.ell,context.sm,c.fp.p,c.f.c[0],cover.k);assert!(verifier::verify(context,cover));assert!(crate::reference::verify(context,cover));let mut mutations=vec![];let mut b=cover.clone();b.branches.pop();mutations.push(b);let mut b=cover.clone();b.branches[1].0=b.branches[0].0;mutations.push(b);let mut b=cover.clone();b.branches[0].0=(b.branches[0].0+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.target=c.add(&target,&d);mutations.push(b);let mut b=cover.clone();b.context.d=c.add(&d,&d);mutations.push(b);let mut b=cover.clone();b.context.ell+=2;mutations.push(b);let mut b=cover.clone();b.context.sm=(sm+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.c.f.c[0]=(cc+1)%p;mutations.push(b);let mut b=cover.clone();b.z=1;mutations.push(b);let mut b=cover.clone();b.reps[0].1=(b.reps[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives[0].points[0].1=(b.primitives[0].points[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives.iter_mut().find(|p|p.a>0).unwrap().a=0;mutations.push(b);let mut b=cover.clone();b.primitives[0].t=p;mutations.push(b);let mut b=cover.clone();b.k=(k+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=(b.branches[0].1.w[0]+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.excluded=!b.branches[0].1.excluded;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w.pop();mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=ell;mutations.push(b);assert_eq!(mutations.len(),18);for b in mutations{assert!(!verifier::verify(&context,&b));assert!(!crate::reference::verify(&context,&b));}}pub fn anchors(context:&Context,cover:&Cover){let f=&context.c.fp;let j=cover.anchor_certificates.iter().position(|p|!p.fallback&&p.reduced).unwrap();let mut cases=vec![];let mut b=cover.clone();b.anchor_certificates.pop();cases.push(b);let mut b=cover.clone();b.anchor_certificates.push(b.anchor_certificates[0].clone());cases.push(b);for field in 0..6{let mut b=cover.clone();let p=&mut b.anchor_certificates[j];let one=hec_native_ic::poly::Poly::one();match field{0=>p.out.v=p.out.v.add(&one,f),1=>p.w=p.w.add(&one,f),2=>p.qa=p.qa.add(&one,f),3=>p.qb=p.qb.add(&one,f),4=>p.gamma=0,_=>p.qc=p.qc.add(&one,f)}cases.push(b);}assert_eq!(cases.len(),8);for b in cases{assert!(!verifier::verify(context,&b));}}
pub fn target_row(context:&Context,cover:&Cover){if let Some(j)=cover.primitives.iter().position(|p|p.a==0){let mut cases=vec![];for field in 0..4{let mut b=cover.clone();let p=&mut b.primitives[j];match field{0=>p.t=1,1=>{p.points.pop();},2=>p.points[0].0=(p.points[0].0+1)%context.c.fp.p,_=>p.a=1}cases.push(b);}for b in cases{assert!(!verifier::verify(context,&b));assert!(!crate::reference::verify(context,&b));}eprintln!("target_row_mutations_rejected_each_verifier=4");}}
